css:
.letter-container {
	font-family: Arial, Helvetica, sans-serif;
	font-size: 11pt;
	line-height: 1.5;
	max-width: 180mm;
	margin: 0 auto;
	padding: 20mm;
}

.letter-head {
	margin-bottom: 25mm;
}

.recipient-address {
	margin-bottom: 20mm;
	white-space: pre-line;
}

.date-field {
	margin-bottom: 15mm;
	text-align: right;
}

.greeting {
	margin-bottom: 12mm;
}

.body-text {
	margin-bottom: 12mm;
	text-align: justify;
}

.body-text p {
	margin-bottom: 8mm;
}

.closing {
	margin-top: 15mm;
}

.signature {
	margin-top: 8mm;
	font-weight: bold;
}

html:
{# Render letterhead - letter_head variable is passed by Frappe #}
{% if letter_head and not no_letterhead %}
<div class="letter-head">{{ letter_head }}</div>
{% endif %}

<div class="letter-container">
	{% set address = None %}
	{% set customer_name = None %}

	{# Get linked address from Contact #}
	{% if doc.links %}
		{% for link in doc.links %}
			{% if link.link_doctype == "Address" and not address %}
				{% set address = frappe.get_doc("Address", link.link_name) %}
			{% elif link.link_doctype == "Customer" and not customer_name %}
				{% set customer_name = link.link_name %}
			{% endif %}
		{% endfor %}
	{% endif %}

	{# If no direct address, try to get from Customer #}
	{% if not address and customer_name %}
		{% set customer_address_name = frappe.db.get_value("Dynamic Link", {"parenttype": "Address", "link_doctype": "Customer", "link_name": customer_name}, "parent") %}
		{% if customer_address_name %}
			{% set address = frappe.get_doc("Address", customer_address_name) %}
		{% endif %}
	{% endif %}

	{# Recipient Address Block #}
	<div class="recipient-address">
		<strong>{{ doc.first_name }} {{ doc.last_name }}</strong><br>
		{% if address %}
			{{ address.address_line1 }}<br>
			{% if address.address_line2 %}{{ address.address_line2 }}<br>{% endif %}
			{% if address.pincode or address.city %}{{ address.pincode or '' }} {{ address.city or '' }}<br>{% endif %}
			{% if address.country %}{{ address.country }}{% endif %}
		{% endif %}
	</div>

	{# Date #}
	{% set today = frappe.utils.nowdate() %}
	{% set formatted_date = frappe.utils.getdate(today).strftime("%d.%m.%Y") %}
	<div class="date-field">{{ formatted_date }}</div>

	{# Greeting #}
	<div class="greeting">
		Guten Tag {{ doc.first_name }} {{ doc.last_name }},
	</div>

	{# Body Text - Lorem Ipsum #}
	<div class="body-text">
		<p>
			Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor 
			incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud 
			exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute 
			irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla 
			pariatur.
		</p>
		<p>
			Nemo enim ipsam voluptatem quia voluptas sit aspernatur aut odit aut fugit, sed 
			quia consequuntur magni dolores eos qui ratione voluptatem sequi nesciunt.
		</p>
	</div>

	{# Closing #}
	<div class="closing">
		Mit freundlichen Grüßen,
	</div>

	{# Organization Name #}
	{% set company_name = frappe.db.get_single_value("Non Profit Settings", "company") %}
	{% if not company_name %}
		{% set company_name = frappe.defaults.get_user_default("company") %}
	{% endif %}
	{% set org_name = frappe.db.get_value("Company", company_name, "company_name") if company_name else None %}
	<div class="signature">
		{{ org_name or '' }}
	</div>
</div>

{# Render letterhead footer - footer variable is passed by Frappe #}
{% if footer and not no_letterhead %}
<div class="letter-head">{{ footer }}</div>
{% endif %}
